import unittest
import math
from candidate import triangle_area

class TestTriangleArea(unittest.TestCase):
    def test_valid_right_triangle(self):
        self.assertAlmostEqual(triangle_area(3, 4, 5), 6.0, places=2)

    def test_valid_equilateral_triangle(self):
        area = (math.sqrt(3) / 4) * 5**2
        self.assertAlmostEqual(triangle_area(5, 5, 5), round(area, 2), places=2)

    def test_valid_isosceles_triangle(self):
        self.assertAlmostEqual(triangle_area(5, 5, 6), 12.0, places=2)

    def test_valid_triangle_with_floats(self):
        self.assertAlmostEqual(triangle_area(3.5, 4.2, 5.1), round(math.sqrt((3.5+4.2+5.1)/2 * ((3.5+4.2+5.1)/2 - 3.5) * ((3.5+4.2+5.1)/2 - 4.2) * ((3.5+4.2+5.1)/2 - 5.1)), 2, places=2)

    def test_area_rounding_small_triangle(self):
        self.assertAlmostEqual(triangle_area(2, 3, 4), 2.90, places=2)

    def test_area_rounding_large_triangle(self):
        side = 1e9
        expected = round((math.sqrt(3) / 4) * side**2, 2)
        self.assertAlmostEqual(triangle_area(side, side, side), expected, places=2)

    def test_area_rounding_very_small_triangle(self):
        small_side = 1e-10
        self.assertAlmostEqual(triangle_area(small_side, small_side, small_side), 0.0, places=2)

    def test_invalid_triangle_sum_equality(self):
        self.assertEqual(triangle_area(1, 1, 2), -1)

    def test_invalid_triangle_negative_side(self):
        self.assertEqual(triangle_area(-1, 2, 3), -1)

    def test_invalid_triangle_zero_side(self):
        self.assertEqual(triangle_area(0, 5, 5), -1)

    def test_invalid_triangle_all_negative(self):
        self.assertEqual(triangle_area(-5, -5, -5), -1)

    def test_type_error_non_numeric_first_argument(self):
        with self.assertRaises(TypeError):
            triangle_area('a', 2, 3)

    def test_type_error_non_numeric_second_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(2, 'b', 3)

    def test_type_error_non_numeric_third_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(2, 3, None)

    def test_type_error_none_first_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(None, 2, 3)

    def test_type_error_none_second_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(2, None, 3)

    def test_type_error_none_third_argument(self):
        with self.assertRaises(TypeError):
            triangle_area(2, 3, None)

    def test_valid_triangle_with_mixed_types(self):
        self.assertAlmostEqual(triangle_area(3, 4.0, 5), 6.0, places=2)

if __name__ == "__main__":
    unittest.main()
